import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  ArrowDown, ArrowDownRight, ArrowRight, ArrowUpRight, Building2, CalendarDays,
  Check, CheckCircle2, ChevronDown, ChevronRight, CircleDollarSign, Clock3,
  Copy, Download, Ellipsis, FileCheck2, FileText, Filter, LifeBuoy, Mail,
  MessageCircle, MoreHorizontal, Phone, Plus, RefreshCw, Search, Send,
  ShieldCheck, SlidersHorizontal, Sparkles, Users, Wallet,
} from 'lucide-react';
import './commercial.css';
import { apiRequest, fetchAllRecords, useWorkspaceRecords } from '../lib/workspace-api.js';
import { completeRequestedServiceCatalog, mergeRequestedServiceCatalog, requestedServiceCatalog } from '../data/service-catalog.js';
import { resolveProposalServices, summarizeProposalServices } from '../data/proposal-services.js';
import { buildServiceProject } from '../data/service-project-template.js';
import { belongsToClient } from '../data/client-link.js';
import { contractText, downloadContract, editableContractStatuses, isLockedContractStatus } from '../data/contract-document.js';

const datasets = { leads: [], clients: [], companies: [], contacts: [], proposals: [], services: [], contracts: [], projects: [], tasks: [] };

const config = {
  crm: { title: 'CRM', eyebrow: 'VISÃO COMERCIAL', description: 'Acompanhe suas oportunidades e relacionamentos em um só lugar.', tab: 'Visão geral', icon: Users },
  leads: { title: 'Leads', eyebrow: 'COMERCIAL / CRM', description: 'Organize os novos contatos e acompanhe cada oportunidade.', tab: 'Leads', icon: Users },
  clientes: { title: 'Clientes', eyebrow: 'COMERCIAL / RELACIONAMENTO', description: 'Seus relacionamentos ativos e o valor que constroem juntos.', tab: 'Clientes', icon: Building2 },
  empresas: { title: 'Empresas', eyebrow: 'COMERCIAL / CADASTROS', description: 'Empresas e organizações da sua carteira comercial.', tab: 'Empresas', icon: Building2 },
  contatos: { title: 'Contatos', eyebrow: 'COMERCIAL / CADASTROS', description: 'Pessoas e decisores ligados às suas oportunidades e clientes.', tab: 'Contatos', icon: Users },
  pipeline: { title: 'Pipeline', eyebrow: 'COMERCIAL / OPORTUNIDADES', description: 'Veja o avanço das oportunidades em cada etapa comercial.', tab: 'Pipeline', icon: ArrowUpRight },
  propostas: { title: 'Propostas', eyebrow: 'COMERCIAL / NEGOCIAÇÃO', description: 'Acompanhe propostas enviadas, aprovações e próximos passos.', tab: 'Propostas', icon: FileText },
  servicos: { title: 'Serviços', eyebrow: 'COMERCIAL / PORTFÓLIO', description: 'Apresente seu catálogo de serviços e condições comerciais.', tab: 'Serviços', icon: Sparkles },
  contratos: { title: 'Contratos', eyebrow: 'COMERCIAL / CLIENTES', description: 'Acompanhe contratos ativos, entregas e datas de renovação.', tab: 'Contratos', icon: FileCheck2 },
};

const normalizePage = (page) => String(page || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const titleFor = (page) => config[normalizePage(page)] || config.crm;
const dataAliases = { clientes: 'clients', empresas: 'companies', contatos: 'contacts', propostas: 'proposals', servicos: 'services', contratos: 'contracts' };
const dataFor = (page) => datasets[dataAliases[normalizePage(page)] || normalizePage(page)] || datasets.leads;

function useCommercialRecords() {
  const leads = useWorkspaceRecords('leads'); const clients = useWorkspaceRecords('clients'); const companies = useWorkspaceRecords('companies');
  const contacts = useWorkspaceRecords('contacts'); const proposals = useWorkspaceRecords('proposals'); const services = useWorkspaceRecords('services'); const contracts = useWorkspaceRecords('contracts');
  const projects = useWorkspaceRecords('projects'); const tasks = useWorkspaceRecords('tasks');
  // Persist the proposal status after its dependent contract/project/tasks. The
  // proposal.accepted event can reach n8n as soon as the API stores that status.
  const stores = { leads, clients, companies, contacts, services, contracts, projects, tasks, proposals };
  const records = Object.fromEntries(Object.entries(stores).map(([key, value]) => [key, value.records]));
  const persist = async (next) => {
    try {
      for (const [key, store] of Object.entries(stores)) {
        const oldRows = store.records; const newRows = next[key] || [];
        const oldIds = new Set(oldRows.map((row) => String(row.id))); const nextIds = new Set(newRows.map((row) => String(row.id)));
        for (const row of newRows) {
          const before = oldRows.find((item) => String(item.id) === String(row.id));
          const payload = Object.fromEntries(Object.entries(row).filter(([field]) => !['id','createdAt','updatedAt'].includes(field)));
          if (!before) await store.create(payload); else if (JSON.stringify(payload) !== JSON.stringify(Object.fromEntries(Object.entries(before).filter(([field]) => !['id','createdAt','updatedAt'].includes(field)))) ) await store.update(row.id, payload);
        }
        for (const row of oldRows) if (!nextIds.has(String(row.id)) && oldIds.has(String(row.id))) await store.remove(row.id);
      }
    } catch (error) { window.dispatchEvent(new CustomEvent('nexo:workspace-error', { detail: error.message })); throw error; }
  };
  const persistServices = async (nextServices) => {
    const oldRows = services.records;
    const oldIds = new Set(oldRows.map((row) => String(row.id)));
    const nextIds = new Set(nextServices.map((row) => String(row.id)));
    for (const row of nextServices) {
      const before = oldRows.find((item) => String(item.id) === String(row.id));
      const payload = Object.fromEntries(Object.entries(row).filter(([field]) => !['id','createdAt','updatedAt'].includes(field)));
      if (!before) await services.create(payload);
      else if (JSON.stringify(payload) !== JSON.stringify(Object.fromEntries(Object.entries(before).filter(([field]) => !['id','createdAt','updatedAt'].includes(field))))) await services.update(row.id, payload);
    }
    for (const row of oldRows) if (!nextIds.has(String(row.id)) && oldIds.has(String(row.id))) await services.remove(row.id);
  };
  const refresh = async () => { await Promise.all(Object.values(stores).map((store) => store.refresh())); };
  return [records, persist, refresh, services.loading, services.error, persistServices];
}

function Avatar({ initials, tone = 'blue', small = false }) {
  return <span className={`com-avatar com-avatar-${tone}${small ? ' com-avatar-small' : ''}`} aria-hidden="true">{initials}</span>;
}

function Badge({ children, tone = 'gray' }) {
  return <span className={`com-badge com-badge-${tone}`}><i />{children}</span>;
}

function Feedback({ message, onClose }) {
  if (!message) return null;
  return <div className="com-feedback" role="status"><CheckCircle2 size={17} />{message}<button onClick={onClose} aria-label="Fechar mensagem">×</button></div>;
}

export default function CommercialScreen({ page }) {
  const externalPage = normalizePage(page || 'crm');
  const [localPage, setLocalPage] = useState(externalPage);
  useEffect(() => setLocalPage(externalPage), [externalPage]);
  const current = titleFor(localPage);
  const key = localPage;
  const recordType = dataAliases[key] || key;
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('Todos');
  const [extraFilters, setExtraFilters] = useState({});
  const [toast, setToast] = useState('');
  const [period, setPeriod] = useState('Últimos 30 dias');
  const [records, persistRecords, refreshRecords, servicesLoading, servicesError, persistServices] = useCommercialRecords();
  const [catalogSeedState, setCatalogSeedState] = useState('idle');
  const catalogSeedStarted = useRef(false);
  const [composer, setComposer] = useState(false);
  const emptyDraft = { title: '', client: '', clientId: '', email: '', phone: '', value: '', detail: '', serviceId: '', serviceIds: [], scope: '', deadline: '', paymentTerms: '50% na aprovação e 50% na entrega' };
  const [draft, setDraft] = useState(emptyDraft);
  const data = Array.isArray(records[recordType]) ? records[recordType].filter((item) => item && typeof item === 'object' && !Array.isArray(item)) : dataFor(localPage);
  const extraFilterFields = useMemo(() => [
    { key: 'source', label: 'Origem' }, { key: 'owner', label: 'Responsável' },
    { key: 'service', label: 'Serviço' }, { key: 'segment', label: 'Segmento' },
    { key: 'city', label: 'Cidade' }, { key: 'status', label: 'Status', read: (item) => item.status || item.stage },
  ].flatMap((field) => {
    const values = [...new Set(data.map((item) => String(field.read ? field.read(item) || '' : item[field.key] || '').trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'pt-BR'));
    return values.length > 1 ? [{ ...field, values }] : [];
  }), [data]);
  const visible = useMemo(() => data.filter((item) => {
    const term = search.trim().toLocaleLowerCase('pt-BR');
    const text = Object.values(item).join(' ').toLocaleLowerCase('pt-BR');
    const status = item.status || item.stage;
    const matchesExtra = extraFilterFields.every((field) => !extraFilters[field.key] || String(field.read ? field.read(item) || '' : item[field.key] || '') === extraFilters[field.key]);
    return (!term || text.includes(term)) && (filter === 'Todos' || status === filter || item.source === filter) && matchesExtra;
  }), [data, search, filter, extraFilters, extraFilterFields]);
  const notify = (message) => { setToast(message); window.clearTimeout(notify.timer); notify.timer = window.setTimeout(() => setToast(''), 3000); };
  const createLabel = key === 'servicos' ? 'Novo serviço' : key === 'clientes' ? 'Adicionar cliente' : key === 'empresas' ? 'Nova empresa' : key === 'contatos' ? 'Novo contato' : key === 'propostas' ? 'Criar proposta' : key === 'contratos' ? 'Novo contrato' : key === 'pipeline' ? 'Nova oportunidade' : 'Adicionar lead';
  const importCatalog = async () => {
    const currentServices = records.services || [];
    const additions = mergeRequestedServiceCatalog(currentServices, requestedServiceCatalog);
    const completedServices = completeRequestedServiceCatalog(currentServices, requestedServiceCatalog);
    const repaired = completedServices.filter((item, index) => JSON.stringify(item) !== JSON.stringify(currentServices[index]));
    if (!additions.length && !repaired.length) { setCatalogSeedState('ready'); notify('Catálogo já completo.'); return true; }
    setCatalogSeedState('loading');
    try {
      await persistServices([...additions, ...completedServices]);
      setCatalogSeedState('ready');
      notify(additions.length ? `${additions.length} itens cadastrados e ${repaired.length} modelos completados.` : `Modelos de proposta e contrato completados em ${repaired.length} serviços.`);
      return true;
    } catch (error) { setCatalogSeedState('error'); notify(error.message || 'Não foi possível completar o catálogo.'); return false; }
  };
  useEffect(() => {
    if (key !== 'servicos' || servicesLoading || servicesError || catalogSeedStarted.current) return;
    const currentServices = records.services || [];
    const additions = mergeRequestedServiceCatalog(currentServices, requestedServiceCatalog);
    const completedServices = completeRequestedServiceCatalog(currentServices, requestedServiceCatalog);
    const repaired = completedServices.some((item, index) => JSON.stringify(item) !== JSON.stringify(currentServices[index]));
    if (!additions.length && !repaired) return;
    catalogSeedStarted.current = true;
    void importCatalog();
  }, [key, servicesLoading, servicesError, records.services]);
  const createRecord = async (event) => {
    event.preventDefault();
    if (!draft.title.trim()) return;
    const title = draft.title.trim();
    const id = Date.now();
    const tone = ['blue', 'green', 'purple', 'amber'][id % 4];
    const common = { name: title, title, initials: title.split(/\s+/).slice(0, 2).map((part) => part[0]).join('').toUpperCase(), tone };
    let entry;
    if (key === 'leads' || key === 'pipeline' || key === 'crm') entry = { ...common, company: draft.client || 'Empresa nao informada', email: draft.email, phone: draft.phone, source: 'Manual', service: draft.detail || 'A definir', value: draft.value ? `R$ ${draft.value}` : 'A definir', stage: 'Novo lead', date: 'Agora' };
    else if (key === 'clientes') entry = { ...common, person: draft.client || 'Contato nao informado', email: draft.email, segment: draft.detail || 'A definir', projects: '0 projetos', value: draft.value ? `R$ ${draft.value}/mes` : 'R$ 0,00', status: 'Ativo', since: 'Cliente desde hoje' };
    else if (key === 'empresas') entry = { ...common, segment: draft.detail || 'A definir', city: 'Nao informado', size: 'A definir', people: '1 contato', status: 'Prospect' };
    else if (key === 'contatos') entry = { ...common, role: draft.detail || 'Contato', company: draft.client || 'Empresa nao informada', email: draft.email, phone: draft.phone, status: 'Contato', last: 'Sem contato registrado' };
    else if (key === 'servicos') entry = { ...common, category: draft.detail || 'Geral', description: draft.client || 'Servico cadastrado pela equipe.', price: draft.value ? `A partir de R$ ${draft.value}` : 'A combinar', cadence: draft.email || 'Projeto fechado', color: tone };
    else if (key === 'propostas') {
      const linkedClient = (records.clients || []).find((client) => String(client.id) === String(draft.clientId)) || (records.clients || []).find((client) => client.name?.trim().toLocaleLowerCase('pt-BR') === draft.client.trim().toLocaleLowerCase('pt-BR'));
      const selectedServices = resolveProposalServices(records.services || [], draft.serviceIds, draft.serviceId);
      const serviceSummary = summarizeProposalServices(selectedServices);
      entry = { ...common, client: draft.client || 'Cliente nao informado', clientId: linkedClient?.id, email: draft.email.trim().toLowerCase(), code: `PROP-${id.toString().slice(-6)}`, value: draft.value ? `R$ ${draft.value}` : 'A definir', status: 'Rascunho', tone: 'gray', date: 'Criada agora', scope: draft.scope || serviceSummary.proposalScope || draft.detail || 'Escopo a detalhar', deadline: draft.deadline || 'A definir', paymentTerms: draft.paymentTerms || 'A combinar', service: serviceSummary.label || draft.detail || 'Servico a definir', serviceId: selectedServices[0]?.id || '', serviceIds: selectedServices.map((service) => service.id) };
    } else {
      const linkedClient = (records.clients || []).find((client) => String(client.id) === String(draft.clientId));
      const serviceTemplate = (records.services || []).find((service) => String(service.id) === String(draft.serviceId));
      const amountText = String(draft.value || '').replace(/[^\d,]/g, '').replace(/\./g, '').replace(',', '.');
      const amount = Number(amountText);
      const scope = draft.scope.trim() || serviceTemplate?.contractTemplate || serviceTemplate?.proposalTemplate || serviceTemplate?.description || '';
      const deadline = draft.deadline.trim() || serviceTemplate?.duration || '';
      if (!linkedClient) { notify('Selecione um cliente cadastrado para criar o contrato.'); return; }
      if (!Number.isFinite(amount) || amount <= 0) { notify('Informe um valor valido para o contrato.'); return; }
      if (!scope.trim()) { notify('Descreva o escopo ou selecione um servico com modelo.'); return; }
      if (!deadline.trim()) { notify('Informe o prazo ou selecione um servico com prazo definido.'); return; }
      entry = { ...common, client: linkedClient.name, clientId: linkedClient.id, email: linkedClient.email || '', code: `CTR-${id.toString().slice(-6)}`, value: amount.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }), status: 'Rascunho', tone: 'gray', renewal: 'A definir', progress: 0, service: serviceTemplate?.name || draft.detail || '', serviceId: serviceTemplate?.id || '', scope, deadline, paymentTerms: draft.paymentTerms || 'A combinar', signatureEvents: [] };
      entry.documentText = contractText(entry);
    }
    const recordKey = ['crm', 'pipeline'].includes(key) ? 'leads' : recordType;
    try { await persistRecords({ ...records, [recordKey]: [entry, ...(records[recordKey] || [])] }); setComposer(false); setDraft({ ...emptyDraft }); notify(`${createLabel.replace(/^(Novo |Adicionar |Criar )/, '')} salvo no workspace.`); }
    catch (error) { notify(error.message || 'Nao foi possivel salvar o registro.'); }
  };

  const sendProposal = async (proposal, to, idempotencyKey, provider = 'resend') => {
    const result = await apiRequest(`/api/workspace/proposals/${proposal.id}/send-email`, { method: 'POST', headers: { 'Idempotency-Key': idempotencyKey }, body: JSON.stringify({ to, provider }) });
    await persistRecords({ ...records, proposals: (records.proposals || []).map((item) => item.id === proposal.id ? { ...item, email: to, status: 'Enviada', tone: 'blue', emailDelivery: { status: 'sent', provider, recipient: to, emailId: result.data.emailId, sentAt: result.data.sentAt }, date: `Enviada em ${new Date(result.data.sentAt).toLocaleDateString('pt-BR')}` } : item) });
    notify(`Proposta enviada para ${to}.`);
    return result;
  };
  const acceptProposal = async (proposal) => {
    const now = new Date().toISOString(); const suffix = now.replace(/\D/g, '').slice(0, 8);
    const selectedServices = resolveProposalServices(records.services || datasets.services, proposal.serviceIds, proposal.serviceId);
    const serviceSummary = summarizeProposalServices(selectedServices);
    const serviceTemplate = selectedServices[0] || (records.services || datasets.services).find((item) => item.name.toLowerCase() === String(proposal.service || '').toLowerCase());
    const contract = { title: proposal.title, client: proposal.client, clientId: proposal.clientId, sourceProposalId: proposal.id, code: `CTR-${suffix}`, value: proposal.value, status: 'Rascunho', tone: 'gray', renewal: 'Vigência a definir', progress: 0, scope: proposal.scope || serviceSummary.contractScope || serviceTemplate?.contractTemplate || proposal.service, service: serviceSummary.label || proposal.service, serviceId: serviceTemplate?.id || '', serviceIds: selectedServices.map((service) => service.id), paymentTerms: proposal.paymentTerms || 'A combinar', deadline: proposal.deadline || serviceTemplate?.duration || 'A definir', signatureEvents: [], documentText: '' };
    contract.documentText = contractText(contract);
    const project = { id: Date.now(), name: proposal.title, client: proposal.client, clientId: proposal.clientId, sourceProposalId: proposal.id, type: serviceSummary.label || proposal.service || 'Projeto comercial', services: serviceSummary.names, status: 'Em andamento', progress: 0, due: proposal.deadline || serviceTemplate?.duration || 'A definir', team: serviceSummary.responsible, tone: serviceTemplate?.color || 'blue', scope: proposal.scope || serviceSummary.proposalScope || serviceTemplate?.description || '' };
    const template = serviceSummary.tasks.length ? serviceSummary.tasks : /site|landing|web/i.test(proposal.title) ? ['Reunir briefing e referências', 'Definir arquitetura e conteúdo', 'Criar primeira versão', 'Revisão interna', 'Apresentar para aprovação', 'Publicar e validar'] : ['Alinhar escopo e objetivos', 'Preparar primeira entrega', 'Revisar internamente', 'Enviar para aprovação do cliente', 'Aplicar ajustes finais', 'Entregar projeto'];
    const projectTasks = template.map((title, index) => ({ id: project.id + index + 1, title, project: project.name, projectId: project.id, client: project.client, clientId: proposal.clientId, sourceProposalId: proposal.id, due: proposal.deadline || 'A definir', assignee: serviceSummary.responsible.join(', '), status: 'A fazer', priority: index === 0 ? 'Alta' : 'Normal' }));
    try {
      const result = await apiRequest(`/api/workspace/proposals/${encodeURIComponent(proposal.id)}/accept`, { method: 'POST', body: JSON.stringify({ contract, project, tasks: projectTasks }) });
      await refreshRecords();
      notify(result.data?.idempotent ? 'Esta proposta já tinha sido convertida em contrato e projeto.' : `Proposta aceita; contrato em rascunho, projeto e ${projectTasks.length} tarefas criados juntos. Revise o contrato antes de enviar para assinatura.`);
    } catch (error) { notify(error.message || 'Não foi possível concluir a aprovação.'); }
  };

  return <main className="commercial-screen">
    <header className="com-page-heading">
      <div><div className="com-breadcrumb">NEXO <ChevronRight size={13} /> COMERCIAL <ChevronRight size={13} /> {current.tab.toUpperCase()}</div><p className="com-eyebrow">{current.eyebrow}</p><h1>{current.title}</h1><p className="com-description">{current.description}</p></div>
      <button className="com-primary" onClick={() => { setDraft({ ...emptyDraft }); setComposer(true); }}><Plus size={17} />{createLabel}<ChevronDown size={14} /></button>
    </header>
    <nav className="com-tabs" aria-label="Módulos comerciais">{Object.entries(config).map(([id, item]) => <button key={id} className={id === key ? 'active' : ''} aria-current={id === key ? 'page' : undefined} onClick={() => { setLocalPage(id); setSearch(''); setFilter('Todos'); }}><item.icon size={14} />{item.tab}</button>)}</nav>
    {key === 'crm' || key === 'pipeline' ? <PipelineView items={records.leads || datasets.leads} onUpdate={(lead, patch) => { const nextLeads = (records.leads || datasets.leads).map((item) => item.name === lead.name ? { ...item, ...patch } : item); const next = { ...records, leads: nextLeads }; if (patch.stage === 'Fechado' && !(records.clients || datasets.clients).some((client) => client.name === lead.company)) next.clients = [{ name: lead.company, person: lead.name, email: lead.email, phone: lead.phone, segment: patch.service || lead.service, services: [patch.service || lead.service].filter(Boolean), projects: '0 projetos', value: patch.value || lead.value, status: 'Ativo', initials: lead.initials, tone: lead.tone, since: 'Cliente desde hoje', notes: '' }, ...(records.clients || datasets.clients)]; persistRecords(next); notify(patch.stage === 'Fechado' ? `${lead.company} convertido em cliente.` : 'Oportunidade atualizada.'); }} onMove={(lead, stage) => { const leads = (records.leads || datasets.leads).map((item) => item.name === lead.name ? { ...item, stage } : item); const next = { ...records, leads }; const known = (records.clients || datasets.clients).some((client) => client.name === lead.company); if (stage === 'Fechado' && !known) next.clients = [{ name: lead.company, person: lead.name, email: lead.email, phone: lead.phone, segment: lead.service, services: [lead.service].filter(Boolean), projects: '0 projetos', value: lead.value, status: 'Ativo', initials: lead.initials, tone: lead.tone, since: 'Cliente desde hoje', notes: '' }, ...(records.clients || datasets.clients)]; persistRecords(next);  notify(stage === 'Fechado' ? `${lead.company} convertido em cliente.` : `${lead.name} movido para ${stage}.`); }} onAction={notify} onSearch={setSearch} search={search} mode={key} /> : key === 'servicos' ? <ServicesView items={visible} totalItems={records.services?.length || 0} clients={records.clients || []} onCreateProject={async (project,tasks) => { await persistRecords({ ...records, projects: [project, ...(records.projects || [])], tasks: [...tasks, ...(records.tasks || [])] }); }} onAction={notify} onUpdate={(record, patch) => { const next = { ...records, services: (records.services || datasets.services).map((item) => item.id === record.id ? { ...item, ...patch } : item) }; persistRecords(next); notify('Serviço atualizado e sincronizado no workspace.'); }} onDelete={(record) => { if (!window.confirm(`Excluir o serviço “${record.name}”?`)) return; persistRecords({ ...records, services: (records.services || datasets.services).filter((item) => item.id !== record.id) }); notify('Serviço removido do workspace.'); }} onImportCatalog={importCatalog} catalogImporting={catalogSeedState === 'loading' || servicesLoading} catalogSeedState={catalogSeedState} search={search} setSearch={setSearch} /> : <ListView page={key} items={visible} search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} extraFilterFields={extraFilterFields} extraFilters={extraFilters} setExtraFilters={setExtraFilters} onAction={notify} onAccept={acceptProposal} onSendProposal={sendProposal} onRefreshRecords={refreshRecords} onUpdate={(record, patch) => { const storeKey = ['crm', 'pipeline'].includes(key) ? 'leads' : recordType; const next = { ...records, [storeKey]: (records[storeKey] || []).map((item) => (item.title || item.name) === (record.title || record.name) ? { ...item, ...patch } : item) }; if (key === 'leads' && patch.stage === 'Fechado' && !(records.clients || []).some((client) => client.name === record.company)) next.clients = [{ name: record.company, person: record.name, email: record.email, phone: record.phone, segment: record.service, services: [record.service].filter(Boolean), projects: '0 projetos', value: record.value, status: 'Ativo', initials: record.initials, tone: record.tone, since: 'Cliente desde hoje' }, ...(records.clients || datasets.clients)]; persistRecords(next); notify(patch.stage === 'Fechado' ? 'Negócio ganho e cliente criado.' : 'Registro atualizado.'); }} onDelete={(record) => { if (!window.confirm(`Excluir “${record.name || record.title}” do workspace?`)) return; persistRecords({ ...records, [recordType]: (records[recordType] || []).filter((item) => (item.title || item.name) !== (record.title || record.name)) }); notify('Registro removido.'); }} />}
    {composer && <div className="com-modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) setComposer(false); }}><form className="com-create-modal" onSubmit={createRecord}><header><div><small>{current.eyebrow}</small><h2>{createLabel}</h2></div><button type="button" aria-label="Fechar" onClick={() => setComposer(false)}>×</button></header><label>{['leads','clientes','empresas','contatos'].includes(key) ? 'Nome' : key === 'servicos' ? 'Nome do serviço' : key === 'propostas' ? 'Título da proposta' : key === 'contratos' ? 'Título do contrato' : 'Nome da oportunidade'}<input autoFocus required value={draft.title} onChange={(e) => setDraft({ ...draft, title: e.target.value })} placeholder="Digite um nome" /></label>{['propostas','contratos'].includes(key) && <label>Vincular cliente cadastrado<select required={key === 'contratos'} value={draft.clientId} onChange={(e) => { const client = (records.clients || []).find((item) => item.id === e.target.value); setDraft({ ...draft, clientId: client?.id || '', client: client?.name || draft.client, email: client?.email || draft.email }); }}><option value="">Selecione um cliente</option>{(records.clients || []).map((client) => <option key={client.id} value={client.id}>{client.name}</option>)}</select></label>}{['leads','clientes','contatos','propostas'].includes(key) && <label>{key === 'contatos' ? 'Empresa' : 'Cliente / empresa'}<input value={draft.client} onChange={(e) => setDraft({ ...draft, clientId: '', client: e.target.value })} /></label>}{['leads','clientes','contatos'].includes(key) && <label>E-mail<input type="email" value={draft.email} onChange={(e) => setDraft({ ...draft, email: e.target.value })} /></label>}{key === 'propostas' && <label>E-mail destinatario<input type="email" value={draft.email} onChange={(e) => setDraft({ ...draft, email: e.target.value })} placeholder="cliente@empresa.com" /></label>}{['leads','contatos'].includes(key) && <label>Telefone<input value={draft.phone} onChange={(e) => setDraft({ ...draft, phone: e.target.value })} /></label>}{!['empresas','contatos'].includes(key) && <label>{key === 'servicos' ? 'Preço base' : 'Valor estimado'}<input required={key === 'contratos'} value={draft.value} onChange={(e) => setDraft({ ...draft, value: e.target.value })} placeholder="Ex.: 2500,00" /></label>}{['propostas','contratos'].includes(key) && <><label>Escopo da proposta/contrato<textarea rows={3} required={key === 'contratos'} value={draft.scope} onChange={(e) => setDraft({ ...draft, scope: e.target.value })} placeholder="Entregaveis, paginas, integracoes e limites do trabalho" /></label><label>Prazo estimado<input required={key === 'contratos'} value={draft.deadline} onChange={(e) => setDraft({ ...draft, deadline: e.target.value })} placeholder="Ex.: 20 dias uteis" /></label><label>Condicoes de pagamento<select value={draft.paymentTerms} onChange={(e) => setDraft({ ...draft, paymentTerms: e.target.value })}><option>50% na aprovacao e 50% na entrega</option><option>100% na aprovacao</option><option>Parcelado em 3 etapas</option><option>Mensal recorrente</option><option>A combinar</option></select></label></>}{key === 'propostas' ? <fieldset className="com-service-picker"><legend>Serviços do catálogo</legend><small>Selecione um ou mais itens; o valor total continua editável.</small>{(records.services || []).map((item) => { const selectedIds = draft.serviceIds?.length ? draft.serviceIds.map(String) : draft.serviceId ? [String(draft.serviceId)] : []; return <label key={item.id}><input type="checkbox" checked={selectedIds.includes(String(item.id))} onChange={(event) => { const ids = new Set(selectedIds); if (event.target.checked) ids.add(String(item.id)); else ids.delete(String(item.id)); const nextIds = [...ids]; const names = (records.services || []).filter((service) => ids.has(String(service.id))).map((service) => service.name); setDraft({ ...draft, serviceIds: nextIds, serviceId: nextIds[0] || '', detail: names.join(' + ') }); }} /><span>{item.catalogGroup ? `${item.catalogGroup} · ` : ''}{item.name}<small>{item.price || 'Preço a definir'}</small></span></label>})}{!(records.services || []).length && <span>Cadastre o catálogo antes de criar propostas com serviços.</span>}</fieldset> : key === 'contratos' ? <label>Serviço do catálogo<select value={draft.serviceId} onChange={(e) => { const selectedService = (records.services || []).find((item) => String(item.id) === e.target.value); const numericPrice = String(selectedService?.price || '').replace(/[^\d,]/g, '').replace(',', '.'); setDraft({ ...draft, detail: selectedService?.name || '', serviceId: selectedService?.id || '', value: numericPrice || draft.value, scope: selectedService?.contractTemplate || selectedService?.proposalTemplate || selectedService?.description || draft.scope, deadline: selectedService?.duration || draft.deadline, paymentTerms: selectedService?.cadence === 'Mensal' ? 'Mensal recorrente' : draft.paymentTerms }); }}><option value="">Selecione um serviço</option>{(records.services || []).map((item) => <option key={item.id} value={item.id}>{item.catalogGroup ? `${item.catalogGroup} · ` : ''}{item.name}{item.price ? ` · ${item.price}` : ' · preço a definir'}</option>)}</select></label> : <label>{key === 'servicos' ? 'Categoria' : key === 'empresas' ? 'Segmento' : key === 'contatos' ? 'Cargo' : 'Serviço / observações'}<input value={draft.detail} onChange={(e) => setDraft({ ...draft, detail: e.target.value })} /></label>}<footer><button type="button" className="com-secondary" onClick={() => setComposer(false)}>Cancelar</button><button type="submit" className="com-primary"><Check size={15} />Salvar</button></footer></form></div>}
    <Feedback message={toast} onClose={() => setToast('')} />
  </main>;
}

function Metric({ label, value, detail, icon: Icon, tone = 'blue', trend }) {
  return <article className="com-metric"><span className={`com-metric-icon ${tone}`}><Icon size={18} /></span><div className="com-metric-copy"><small>{label}</small><strong>{value}</strong><span className={trend?.startsWith('-') ? 'down' : 'up'}>{trend && (trend.startsWith('-') ? <ArrowDownRight size={13} /> : <ArrowUpRight size={13} />)}{trend} <i>{detail}</i></span></div></article>;
}

function StatusControl({ page, statusDraft, setStatusDraft }) {
  const options = page === 'leads'
    ? ['Novo lead', 'Contato realizado', 'Reunião agendada', 'Diagnóstico', 'Proposta enviada', 'Negociação', 'Fechado', 'Perdido']
    : page === 'propostas'
      ? ['Rascunho', 'Enviada', 'Visualizada', 'Em negociação', 'Recusada', 'Expirada']
      : page === 'contratos'
        ? editableContractStatuses
        : page === 'empresas'
          ? ['Prospect', 'Cliente', 'Inativo']
          : page === 'contatos'
            ? ['Decisor', 'Influenciador', 'Contato']
            : ['Ativo', 'Em atenção', 'Inativo'];
  const existingSigningState = page === 'contratos' && isLockedContractStatus(statusDraft) && !options.includes(statusDraft);
  const existingApprovedProposalState = page === 'propostas' && statusDraft === 'Aprovada';
  return <label>Status / etapa<select value={statusDraft} onChange={(event) => setStatusDraft(event.target.value)}>{existingSigningState && <option value={statusDraft} disabled>{statusDraft} · estado já registrado</option>}{existingApprovedProposalState && <option value={statusDraft} disabled>Aprovada · convertida</option>}{options.map((option) => <option key={option}>{option}</option>)}</select>{page === 'contratos' && <small>Sem provedor de assinatura conectado, o Nexo não permite marcar um contrato como assinado ou ativo.</small>}{existingApprovedProposalState && <small>A aprovação cria o contrato, o projeto e suas tarefas em conjunto; esse status não pode ser definido manualmente.</small>}</label>;
}

function Toolbar({ search, setSearch, filter, setFilter, filters = ['Todos'], placeholder = 'Buscar...', extraFilterFields = [], extraFilters = {}, onExtraFilterChange = () => {} }) {
  const [filtersOpen, setFiltersOpen] = useState(false);
  const activeExtraFilters = Object.values(extraFilters).filter(Boolean).length;
  return <div className="com-toolbar"><label className="com-search"><Search size={17} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={placeholder} aria-label={placeholder} />{search && <button type="button" aria-label="Limpar busca" onClick={() => setSearch('')}>×</button>}</label><label className="com-filter"><SlidersHorizontal size={15} /><select value={filter} onChange={(event) => setFilter(event.target.value)} aria-label="Filtrar resultados">{filters.map((item) => <option key={item}>{item}</option>)}</select><ChevronDown size={14} /></label><div className="com-more-filter-wrap"><button type="button" className={'com-icon-action ' + (filtersOpen || activeExtraFilters ? 'active' : '')} aria-label="Mais filtros" title="Mais filtros" aria-expanded={filtersOpen} aria-controls="commercial-extra-filters" onClick={() => setFiltersOpen((open) => !open)}><Filter size={16} />{activeExtraFilters > 0 && <span>{activeExtraFilters}</span>}</button>{filtersOpen && <section className="com-extra-filters" id="commercial-extra-filters" aria-label="Filtros adicionais"><header><strong>Filtros adicionais</strong><button type="button" onClick={() => extraFilterFields.forEach((field) => onExtraFilterChange(field.key, ''))}>Limpar</button></header>{extraFilterFields.length ? extraFilterFields.map((field) => <label key={field.key}>{field.label}<select value={extraFilters[field.key] || ''} onChange={(event) => onExtraFilterChange(field.key, event.target.value)}><option value="">Todos</option>{field.values.map((value) => <option key={value} value={value}>{value}</option>)}</select></label>) : <p>Não há filtros adicionais para os registros atuais.</p>}</section>}</div></div>;
}

function ClientProfileModal({ client: initialClient, onClose, onUpdate, onAction }) {
  const [client, setClient] = useState(initialClient);
  const [tab, setTab] = useState('Resumo');
  const [note, setNote] = useState('');
  const [contacts, setContacts] = useState(Array.isArray(initialClient.contacts) ? initialClient.contacts.filter((person) => person && typeof person === 'object' && !Array.isArray(person)) : []);
  const [contactDraft, setContactDraft] = useState({ name: '', role: '', email: '', phone: '' });
  const [related, setRelated] = useState({});
  const [projectModal, setProjectModal] = useState(false);
  const [projectSaving, setProjectSaving] = useState(false);
  const [projectDraft, setProjectDraft] = useState({ name: '', type: 'Site institucional', due: '', detail: '' });
  const tabs = ['Resumo', 'Serviços', 'Projetos', 'Financeiro', 'Comunicação', 'Arquivos', 'Suporte', 'Histórico'];
  useEffect(() => {
    let active = true;
    const resources = ['projects', 'tasks', 'contracts', 'inbox', 'files', 'tickets', 'approvals', 'events'];
    (async () => {
      const entries = await Promise.all([
        ...resources.map(async (name) => [name, await fetchAllRecords(`/api/workspace/${name}`)]),
        (async () => ['billing', await fetchAllRecords('/api/billing/orders')])(),
        (async () => ['subscriptions', await fetchAllRecords('/api/billing/subscriptions')])(),
      ]);
      if (active) setRelated(Object.fromEntries(entries));
    })().catch(() => { if (active) setRelated({}); });
    return () => { active = false; };
  }, [initialClient.id]);
  const projects = (related.projects || []).filter((item) => belongsToClient(item, client, item.client));
  const tasks = (related.tasks || []).filter((item) => belongsToClient(item, client, item.client));
  const billing = (related.billing || []).filter((item) => belongsToClient(item, client, item.clientName || item.client));
  const contracts = (related.contracts || []).filter((item) => belongsToClient(item, client, item.client));
  const subscriptions = (related.subscriptions || []).filter((item) => belongsToClient(item, client, item.clientName || item.client));
  const messages = (related.inbox || []).filter((item) => belongsToClient(item, client, item.company));
  const files = (related.files || []).filter((item) => belongsToClient(item, client, item.client));
  const tickets = (related.tickets || []).filter((item) => belongsToClient(item, client, item.client));
  const approvals = (related.approvals || []).filter((item) => belongsToClient(item, client, item.client));
  const activity = (related.events || []).filter((item) => belongsToClient(item, client, item.client));
  const notes = Array.isArray(client.notes) ? client.notes : [];
  const openTab = (page) => { onClose(); window.dispatchEvent(new CustomEvent('nexo:navigate', { detail: page })); };
  const createProject = async (event) => {
    event.preventDefault();
    if (!projectDraft.name.trim()) return;
    setProjectSaving(true);
    try {
      const result = await apiRequest('/api/workspace/projects', { method: 'POST', body: JSON.stringify({ data: { name: projectDraft.name.trim(), client: client.name, clientId: client.id, type: projectDraft.type, detail: projectDraft.detail.trim(), status: 'Em andamento', progress: 0, due: projectDraft.due || 'A definir', team: [], source: 'Ficha do cliente' } }) });
      setRelated((current) => ({ ...current, projects: [result.data, ...(current.projects || [])] }));
      setProjectDraft({ name: '', type: 'Site institucional', due: '', detail: '' });
      setProjectModal(false);
      setTab('Projetos');
      onAction(`Projeto criado para ${client.name}.`);
    } catch (error) { onAction(error.message || 'Não foi possível criar o projeto no workspace.'); }
    finally { setProjectSaving(false); }
  };
  const saveProfile = (event) => { event.preventDefault(); onUpdate(client); onAction('Perfil do cliente enviado ao workspace.'); };
  const addNote = (event) => { event.preventDefault(); if (!note.trim()) return; const next = [{ text: note.trim(), at: new Date().toISOString() }, ...notes]; const updated = { ...client, notes: next }; setClient(updated); onUpdate(updated); setNote(''); onAction('Nota enviada ao histórico do cliente.'); };
  const liveFeed = [
    ...activity.map((item) => ({ title: item.title || item.type || 'Atividade registrada', detail: item.at ? new Date(item.at).toLocaleString('pt-BR') : 'Histórico do workspace', kind: 'Atividade' })),
    ...notes.map((item) => ({ title: item.text, detail: item.at ? new Date(item.at).toLocaleString('pt-BR') : 'Nota adicionada', kind: 'Nota' })),
    ...tasks.map((item) => ({ title: item.title, detail: `${item.project || 'Tarefa'} · ${item.status || 'Pendente'}`, kind: 'Tarefa' })),
    ...billing.map((item) => ({ title: item.description || 'Cobrança', detail: `${item.status || 'Em aberto'} · vence ${item.due || 'a definir'}`, kind: 'Financeiro' })),
    ...approvals.map((item) => ({ title: item.title, detail: `${item.status || 'Aguardando'} · ${item.project || 'Aprovação'}`, kind: 'Aprovação' })),
  ].slice(0, 8);
  const addContact = (event) => { event.preventDefault(); if (!contactDraft.name.trim()) return; const next = [{ ...contactDraft, id: Date.now() }, ...contacts]; setContacts(next); const updated = { ...client, contacts: next }; setClient(updated); onUpdate(updated); setContactDraft({ name: '', role: '', email: '', phone: '' }); onAction('Contato adicionado à ficha do cliente.'); };
  const setField = (field, value) => setClient((current) => ({ ...current, [field]: value }));
  return <div className="com-client-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="com-client-profile" role="dialog" aria-modal="true" aria-label={`Perfil de ${client.name}`}>
    <header className="com-client-head"><div className="com-client-identity"><Avatar initials={client.initials} tone={client.tone} /><div><div className="com-client-title-line"><h2>{client.name}</h2><Badge tone={client.status === 'Ativo' ? 'green' : 'amber'}>{client.status}</Badge></div><p>{client.segment || 'Segmento não informado'} · {client.since || 'Cliente cadastrado'}</p></div></div><div className="com-client-head-actions"><a href={`mailto:${client.email || ''}`} className="com-secondary"><Mail size={14} />E-mail</a><a href={`https://wa.me/${String(client.phone || '').replace(/\D/g, '')}`} target="_blank" rel="noreferrer" className="com-secondary"><Phone size={14} />WhatsApp</a><button className="com-close-button" aria-label="Fechar perfil" onClick={onClose}>×</button></div></header>
    <div className="com-client-summary"><article><small>Receita mensal</small><b>{client.value || 'Não informada'}</b></article><article><small>Projetos ativos</small><b>{projects.filter((project) => project.status !== 'Concluído').length}</b></article><article><small>Cobranças abertas</small><b>{billing.filter((bill) => !['Paga','Cancelada'].includes(bill.status)).length}</b></article><article><small>Último contato</small><b>{client.lastContact || messages[0]?.time || 'Sem registro'}</b></article></div>
    <nav className="com-client-tabs" aria-label="Seções da ficha do cliente">{tabs.map((item) => <button key={item} className={tab === item ? 'active' : ''} onClick={() => setTab(item)}>{item}</button>)}</nav>
    <div className="com-client-body"><div className="com-client-content">
      {tab === 'Resumo' && <div className="com-client-overview"><form className="com-client-info" onSubmit={saveProfile}><div className="com-client-section-heading"><div><h3>Dados da empresa</h3><p>Informações principais para relacionamento e faturamento.</p></div><button type="submit" className="com-primary"><Check size={14}/>Salvar perfil</button></div><div className="com-client-fields"><label>Nome da empresa<input value={client.name || ''} onChange={(e) => setField('name',e.target.value)} /></label><label>Segmento<input value={client.segment || ''} onChange={(e) => setField('segment',e.target.value)} /></label><label>CNPJ / documento<input value={client.document || ''} onChange={(e) => setField('document',e.target.value)} /></label><label>Site<input value={client.website || ''} onChange={(e) => setField('website',e.target.value)} /></label><label>Endereço<input value={client.address || ''} onChange={(e) => setField('address',e.target.value)} /></label><label>Status<select value={client.status || 'Ativo'} onChange={(e) => setField('status',e.target.value)}><option>Ativo</option><option>Em atenção</option><option>Inativo</option></select></label><label>Serviços contratados<input value={(client.services || []).join(', ')} onChange={(e) => setField('services',e.target.value.split(',').map((s)=>s.trim()).filter(Boolean))} placeholder="Separe os serviços por vírgula" /></label><label>Observações<textarea value={client.notes || ''} onChange={(e) => setField('notes',e.target.value)} rows="3" /></label></div></form><section className="com-client-info"><div className="com-client-section-heading"><div><h3>Contatos</h3><p>Pessoas vinculadas à empresa.</p></div></div><article className="com-client-contact-card"><span className="com-client-contact-avatar">{(client.person || 'C').split(/\s+/).map((x)=>x[0]).slice(0,2).join('')}</span><div><b>{client.person || 'Contato principal'}</b><small>Contato principal · {client.email || 'E-mail não informado'}</small><small>{client.phone || 'Telefone não informado'}</small></div><a href={`mailto:${client.email || ''}`} aria-label="Enviar e-mail"><Mail size={15}/></a></article>{contacts.map((person)=><article className="com-client-contact-card" key={person.id}><span className="com-client-contact-avatar secondary">{person.name.split(/\s+/).map((x)=>x[0]).slice(0,2).join('')}</span><div><b>{person.name}</b><small>{person.role || 'Contato'} · {person.email}</small><small>{person.phone}</small></div></article>)}<form className="com-add-contact-form" onSubmit={addContact}><b>Adicionar contato</b><div className="com-client-fields"><input aria-label="Nome do contato" required placeholder="Nome" value={contactDraft.name} onChange={(e)=>setContactDraft({...contactDraft,name:e.target.value})}/><input aria-label="Cargo do contato" placeholder="Cargo" value={contactDraft.role} onChange={(e)=>setContactDraft({...contactDraft,role:e.target.value})}/><input aria-label="E-mail do contato" type="email" placeholder="E-mail" value={contactDraft.email} onChange={(e)=>setContactDraft({...contactDraft,email:e.target.value})}/><input aria-label="Telefone do contato" placeholder="Telefone" value={contactDraft.phone} onChange={(e)=>setContactDraft({...contactDraft,phone:e.target.value})}/></div><button className="com-secondary" type="submit"><Plus size={13}/>Adicionar contato</button></form></section></div>}
      {tab === 'Serviços' && <section className="com-client-info"><div className="com-client-section-heading"><div><h3>Serviços contratados</h3><p>Catálogo, recorrência e valores vinculados a esta conta.</p></div><button className="com-secondary" onClick={()=>openTab('Serviços')}>Abrir catálogo <ArrowRight size={14}/></button></div>{(client.services || []).map((service)=><article className="com-client-row" key={service}><span className="com-client-row-icon"><Sparkles size={16}/></span><div><b>{service}</b><small>{datasets.services.find((item)=>item.name===service)?.category || 'Serviço contratado'}</small></div><span>{datasets.services.find((item)=>item.name===service)?.cadence || 'Condição conforme contrato'}</span></article>)}{!client.services?.length&&<EmptyState noun="serviços" onClear={()=>openTab('Serviços')}/>}<div className="com-client-actions"><button className="com-primary" onClick={()=>openTab('Propostas')}><Plus size={14}/>Criar proposta</button><button className="com-secondary" onClick={()=>openTab('Contratos')}>Ver contratos</button></div></section>}
      {tab === 'Projetos' && <section className="com-client-info"><div className="com-client-section-heading"><div><h3>Projetos e tarefas</h3><p>Entregas e pendências relacionadas a {client.name}.</p></div><button type="button" className="com-primary" onClick={()=>setProjectModal(true)}><Plus size={14}/>Novo projeto</button></div>{projects.map((project)=><article className="com-client-project" key={project.id}><div><b>{project.name}</b><small>{project.type || 'Projeto'} · prazo {project.due || 'a definir'}</small></div><Badge tone={project.status==='Concluído'?'green':'blue'}>{project.status}</Badge><div className="com-client-progress"><i style={{width:`${project.progress || 0}%`}}/></div><small>{project.progress || 0}% concluído</small></article>)}{tasks.map((task)=><article className="com-client-row" key={task.id}><CheckCircle2 size={15}/><div><b>{task.title}</b><small>{task.project} · {task.assignee}</small></div><Badge tone={task.status==='Concluída'?'green':'amber'}>{task.status}</Badge></article>)}{!projects.length&&!tasks.length&&<EmptyState noun="projetos" onClear={()=>setProjectModal(true)}/>}</section>}
      {tab === 'Financeiro' && <section className="com-client-info"><div className="com-client-section-heading"><div><h3>Financeiro e contratos</h3><p>Cobranças, recorrências e vigência dos contratos.</p></div><button className="com-primary" onClick={()=>openTab('Cobranças')}><Plus size={14}/>Nova cobrança</button></div>{contracts.map((contract)=><article className="com-client-row" key={contract.code}><FileCheck2 size={16}/><div><b>{contract.title}</b><small>{contract.code} · {contract.renewal}</small></div><strong>{contract.value}</strong><Badge tone={contract.tone}>{contract.status}</Badge></article>)}{subscriptions.map((subscription)=><article className="com-client-row" key={subscription.id}><RefreshCw size={15}/><div><b>{subscription.service}</b><small>{subscription.cycle} · {subscription.nextDue}</small></div><strong>{new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(subscription.amount)}</strong><Badge tone={subscription.status==='Ativa'?'green':'amber'}>{subscription.status}</Badge></article>)}{billing.map((bill)=><article className="com-client-row" key={bill.id}><CircleDollarSign size={15}/><div><b>{bill.description}</b><small>Vence {bill.due}</small></div><strong>{new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(bill.amount)}</strong><Badge tone={bill.status==='Paga'?'green':'amber'}>{bill.status}</Badge></article>)}{!contracts.length&&!subscriptions.length&&!billing.length&&<EmptyState noun="registros financeiros" onClear={()=>openTab('Cobranças')}/>}</section>}
      {tab === 'Comunicação' && <section className="com-client-info"><div className="com-client-section-heading"><div><h3>Comunicação</h3><p>Conversas e aprovações relacionadas.</p></div><button className="com-primary" onClick={()=>openTab('Caixa de entrada')}><MessageCircle size={14}/>Abrir atendimento</button></div>{messages.map((message)=><article className="com-client-row" key={message.name}><MessageCircle size={16}/><div><b>{message.name}</b><small>{message.time} · {message.text}</small></div><Badge>{message.unread ? `${message.unread} não lidas` : 'WhatsApp'}</Badge></article>)}{approvals.map((approval)=><article className="com-client-row" key={approval.id}><CheckCircle2 size={15}/><div><b>{approval.title}</b><small>{approval.project} · enviado {approval.sent}</small></div><Badge tone={approval.status==='Aprovado'?'green':'amber'}>{approval.status}</Badge></article>)}{!messages.length&&!approvals.length&&<EmptyState noun="conversas" onClear={()=>openTab('Caixa de entrada')}/>}</section>}
      {tab === 'Arquivos' && <section className="com-client-info"><div className="com-client-section-heading"><div><h3>Arquivos do cliente</h3><p>Documentos e materiais vinculados aos projetos.</p></div><button className="com-primary" onClick={()=>openTab('Arquivos')}><Plus size={14}/>Adicionar arquivo</button></div>{files.map((file)=><article className="com-client-row" key={file.id}><FileText size={16}/><div><b>{file.name}</b><small>{file.project} · {file.date}</small></div><span>{file.size}</span></article>)}{!files.length&&<EmptyState noun="arquivos" onClear={()=>openTab('Arquivos')}/>}</section>}
      {tab === 'Suporte' && <section className="com-client-info"><div className="com-client-section-heading"><div><h3>Suporte e tickets</h3><p>Solicitações técnicas abertas por este cliente.</p></div><button className="com-primary" onClick={()=>openTab('Tickets')}><Plus size={14}/>Novo ticket</button></div>{tickets.map((ticket)=><article className="com-client-row" key={ticket[0]}><LifeBuoy size={16}/><div><b>{ticket[1]}</b><small>{ticket[0]} · {ticket[5]}</small></div><Badge tone={ticket[4]==='Resolvido'?'green':'amber'}>{ticket[4]}</Badge></article>)}{!tickets.length&&<EmptyState noun="tickets" onClear={()=>openTab('Tickets')}/>}</section>}
      {tab === 'Histórico' && <section className="com-client-info"><div className="com-client-section-heading"><div><h3>Histórico do relacionamento</h3><p>Notas e eventos ligados a {client.name}.</p></div></div><form className="com-client-note-form" onSubmit={addNote}><textarea rows="2" value={note} onChange={(e)=>setNote(e.target.value)} placeholder="Registrar uma nota da reunião ou próximo passo…"/><button className="com-primary" type="submit"><Plus size={14}/>Adicionar nota</button></form>{notes.map((item,index)=><article className="com-client-history-row" key={`${item.at}-${index}`}><span className="com-history-dot"/><div><b>{item.text}</b><small>{new Date(item.at).toLocaleString('pt-BR')}</small></div></article>)}{activity.map((item,index)=><article className="com-client-history-row" key={`${item.at}-${index}`}><span className="com-history-dot blue"/><div><b>{item.title || item.type}</b><small>{new Date(item.at).toLocaleString('pt-BR')} · evento registrado no workspace</small></div></article>)}{!notes.length&&!activity.length&&<EmptyState noun="atividades" onClear={()=>setTab('Resumo')}/>}</section>}
    </div><aside className="com-client-live-feed"><div className="com-client-feed-heading"><div><h3>Atividade recente</h3><p>Movimentações desta conta</p></div><span><i/> Atualizado</span></div><div className="com-client-feed-list">{liveFeed.map((item,index)=><article className="com-client-feed-item" key={`${item.kind}-${index}`}><span className={`com-client-feed-dot tone-${index % 4}`}><i/></span><div><small>{item.kind}</small><b>{item.title}</b><p>{item.detail}</p></div></article>)}{!liveFeed.length&&<div className="com-client-feed-empty"><Clock3 size={18}/><span>As próximas tarefas, cobranças e interações aparecerão aqui.</span></div>}</div><div className="com-client-quick-actions"><h4>Ações rápidas</h4><button onClick={()=>{setTab('Projetos');setProjectModal(true)}}><CheckCircle2 size={15}/>Criar projeto<ChevronRight size={14}/></button><button onClick={()=>openTab('Propostas')}><FileText size={15}/>Criar proposta<ChevronRight size={14}/></button><button onClick={()=>openTab('Cobranças')}><CircleDollarSign size={15}/>Gerar cobrança<ChevronRight size={14}/></button><button onClick={()=>openTab('Caixa de entrada')}><MessageCircle size={15}/>Abrir atendimento<ChevronRight size={14}/></button></div><div className="com-client-feed-contact"><span className="com-client-feed-contact-icon"><Building2 size={16}/></span><div><small>Contato principal</small><b>{client.person || 'Não informado'}</b><span>{client.email || 'Cadastre um e-mail'}</span></div></div></aside></div><footer className="com-client-footer"><span><ShieldCheck size={14}/>Ficha sincronizada no workspace · publicação do portal ainda não configurada</span><button className="com-secondary" onClick={()=>{window.dispatchEvent(new CustomEvent('nexo:navigate',{detail:'Portal do cliente'}));onAction('Configure a publicação do portal para compartilhar acesso externo.');}}><Copy size={13}/>Configurar portal</button></footer>
    {projectModal && <div className="com-modal-backdrop" role="presentation" onMouseDown={(event)=>{if(event.target===event.currentTarget&&!projectSaving)setProjectModal(false)}}><form className="com-create-modal" role="dialog" aria-modal="true" aria-labelledby="client-project-title" onSubmit={createProject}><header><div><small>CLIENTE · {client.name}</small><h2 id="client-project-title">Novo projeto</h2></div><button type="button" aria-label="Fechar" disabled={projectSaving} onClick={()=>setProjectModal(false)}>×</button></header><label>Nome do projeto<input autoFocus required maxLength="140" value={projectDraft.name} onChange={(event)=>setProjectDraft({...projectDraft,name:event.target.value})} placeholder="Ex.: Novo site institucional"/></label><label>Tipo de serviço<select value={projectDraft.type} onChange={(event)=>setProjectDraft({...projectDraft,type:event.target.value})}>{['Site institucional','Landing page','Loja virtual','Aplicativo','Sistema web','Automação','Manutenção','Outro'].map((type)=><option key={type}>{type}</option>)}</select></label><label>Prazo previsto<input type="date" value={projectDraft.due} onChange={(event)=>setProjectDraft({...projectDraft,due:event.target.value})}/></label><label>Escopo e observações<textarea rows="3" value={projectDraft.detail} onChange={(event)=>setProjectDraft({...projectDraft,detail:event.target.value})} placeholder="Objetivo, entregas e informações iniciais"/></label><p>O projeto será salvo no workspace e vinculado a {client.name}.</p><footer><button type="button" className="com-secondary" disabled={projectSaving} onClick={()=>setProjectModal(false)}>Cancelar</button><button type="submit" className="com-primary" disabled={projectSaving}><Plus size={14}/>{projectSaving?'Criando…':'Criar projeto'}</button></footer></form></div>}
  </section></div>;
}

function ListView({ page, items, search, setSearch, filter, setFilter, extraFilterFields = [], extraFilters = {}, setExtraFilters = () => {}, onAction, onUpdate, onDelete, onAccept, onSendProposal, onRefreshRecords }) {
  const [selectedItem, setSelectedItem] = useState(null);
  const [statusDraft, setStatusDraft] = useState('');
  const [sendTo, setSendTo] = useState('');
  const [emailProvider, setEmailProvider] = useState('resend');
  const [sendingProposal, setSendingProposal] = useState(false);
  const [retryKey, setRetryKey] = useState('');
  const [signerName, setSignerName] = useState('');
  const [signerEmail, setSignerEmail] = useState('');
  const [contractDocDraft, setContractDocDraft] = useState('');
  const [sendingContract, setSendingContract] = useState(false);
  const [syncingContract, setSyncingContract] = useState(false);
  const sendContract = async () => {
    if (!selectedItem || !signerName.trim() || !signerEmail.trim()) return;
    if (/\[[^\]]{2,100}\]/.test(contractDocDraft)) { onAction('Preencha os campos entre colchetes antes de enviar o contrato.'); return; }
    if (!window.confirm(`Ativar o envelope Clicksign e enviar o contrato para ${signerEmail.trim()}? A Clicksign notificara o signatario por e-mail.`)) return;
    setSendingContract(true);
    try {
      const result = await apiRequest(`/api/integrations/clicksign/contracts/${selectedItem.id}/send`, { method: 'POST', body: JSON.stringify({ signerName: signerName.trim(), signerEmail: signerEmail.trim(), documentText: contractDocDraft }) });
      const saved = result.data;
      await onRefreshRecords?.();
      setSelectedItem(saved);
      onAction(result.warning || (result.notificationSent ? `Contrato ativado e notificacao enviada para ${signerEmail.trim()}.` : 'Envelope ativado na Clicksign.'));
    } catch (error) { onAction(error.message || 'Nao foi possivel enviar o contrato para assinatura.'); }
    finally { setSendingContract(false); }
  };
  const syncContract = async () => {
    if (!selectedItem || syncingContract) return;
    setSyncingContract(true);
    try {
      const result = await apiRequest(`/api/integrations/clicksign/contracts/${selectedItem.id}/sync`, { method: 'POST', body: '{}' });
      const saved = result.data;
      await onRefreshRecords?.();
      setSelectedItem(saved);
      onAction(`Status Clicksign sincronizado: ${saved.status}.`);
    } catch (error) { onAction(error.message || 'Nao foi possivel sincronizar o contrato.'); }
    finally { setSyncingContract(false); }
  };
  const notifyContractSigner = async () => {
    if (!selectedItem) return;
    try {
      const result = await apiRequest(`/api/integrations/clicksign/contracts/${selectedItem.id}/notify`, { method: 'POST', body: '{}' });
      await onRefreshRecords?.();
      setSelectedItem(result.data);
      onAction('Notificacao de assinatura reenviada pela Clicksign.');
    } catch (error) { onAction(error.message || 'Nao foi possivel reenviar a notificacao.'); }
  };
  const titles = { leads: ['Nome', 'Empresa e serviço', 'Origem', 'Etapa', 'Valor estimado', 'Última atividade'], clientes: ['Cliente', 'Contato principal', 'Relacionamento', 'Projetos', 'Receita mensal', 'Status'], empresas: ['Empresa', 'Segmento', 'Localização', 'Porte', 'Contatos', 'Tipo'], contatos: ['Contato', 'Cargo e empresa', 'E-mail', 'Telefone', 'Último contato', 'Perfil'], propostas: ['Proposta', 'Cliente', 'Código', 'Valor', 'Status', 'Atualização'], contratos: ['Contrato', 'Cliente', 'Código', 'Valor', 'Vigência', 'Status'] };
  const label = { leads: 'leads', clientes: 'clientes', empresas: 'empresas', contatos: 'contatos', propostas: 'propostas', contratos: 'contratos' }[page];
  const filters = page === 'leads' ? ['Todos', 'Novo lead', 'Contato realizado', 'Reunião agendada', 'Proposta enviada', 'Site', 'Instagram', 'Indicação', 'Tráfego pago'] : page === 'propostas' ? ['Todos', 'Aguardando resposta', 'Em negociação', 'Aprovada', 'Rascunho', 'Expirada'] : page === 'contratos' ? ['Todos', 'Ativo', 'Renovação próxima', 'Concluído'] : page === 'clientes' ? ['Todos', 'Ativo', 'Em atenção'] : page === 'empresas' ? ['Todos', 'Cliente', 'Prospect'] : ['Todos', 'Decisor', 'Influenciador'];
  const totalValue = items.reduce((sum, item) => sum + (Number(String(item.value || '').replace(/[^\d,]/g, '').replace(',', '.')) || 0), 0);
  const amountLabel = `R$ ${totalValue.toLocaleString('pt-BR')}`;
  const stats = page === 'leads' ? [['Leads ativos', String(items.filter((item) => !['Fechado', 'Perdido'].includes(item.stage)).length), `${items.length} no cadastro`, Users, 'blue'], ['Valor no pipeline', amountLabel, 'soma dos valores informados', CircleDollarSign, 'green'], ['Taxa de conversão', `${Math.round(items.filter((item) => item.stage === 'Fechado').length / Math.max(items.length, 1) * 100)}%`, 'negócios fechados', ArrowUpRight, 'purple'], ['Tempo de resposta', '—', 'sem histórico conectado', Clock3, 'amber']] : page === 'clientes' ? [['Clientes ativos', String(items.filter((item) => item.status === 'Ativo').length), `${items.length} na carteira`, Building2, 'blue'], ['Receita recorrente', amountLabel, 'valores cadastrados', Wallet, 'green'], ['Projetos ativos', String(items.reduce((sum, item) => sum + (Number.parseInt(item.projects, 10) || 0), 0)), 'projetos informados', FileText, 'purple'], ['Renovações próximas', '—', 'datas dos contratos', CalendarDays, 'amber']] : page === 'propostas' ? [['Em aberto', String(items.filter((item) => !['Aprovada', 'Recusada', 'Expirada'].includes(item.status)).length), 'aguardando ou em negociação', FileText, 'blue'], ['Valor proposto', amountLabel, 'soma das propostas', CircleDollarSign, 'green'], ['Taxa de aprovação', `${Math.round(items.filter((item) => item.status === 'Aprovada').length / Math.max(items.length, 1) * 100)}%`, 'propostas aprovadas', CheckCircle2, 'purple'], ['Tempo de fechamento', '—', 'sem histórico conectado', Clock3, 'amber']] : page === 'contratos' ? [['Contratos ativos', String(items.filter((item) => ['Ativo', 'Assinado'].includes(item.status)).length), `${items.length} contratos`, FileCheck2, 'blue'], ['Receita mensal', amountLabel, 'valores cadastrados', CircleDollarSign, 'green'], ['Renovam em breve', String(items.filter((item) => item.status === 'Renovação próxima').length), 'ver datas de vigência', CalendarDays, 'amber'], ['Valor contratado', amountLabel, 'soma dos contratos', Wallet, 'purple']] : null;
  return <>
    {stats && <div className="com-metrics">{stats.map(([label, value, detail, Icon, tone]) => <Metric key={label} {...{ label, value, detail, icon: Icon, tone }} />)}</div>}
    <section className="com-panel"><div className="com-panel-heading"><div><h2>{page === 'leads' ? 'Todos os leads' : page === 'clientes' ? 'Sua carteira' : page === 'empresas' ? 'Empresas cadastradas' : page === 'contatos' ? 'Pessoas e decisores' : page === 'propostas' ? 'Todas as propostas' : 'Todos os contratos'}</h2><p>{items.length} {label} encontrados <span>·</span> Atualizado há poucos minutos</p></div><div className="com-toolbar-actions"><button className="com-secondary" onClick={() => onAction('Relatório preparado para exportação.') }><Download size={15} /> Exportar</button><button className="com-secondary square" aria-label="Mais opções" onClick={() => onAction('Mais opções de exibição.') }><MoreHorizontal size={17} /></button></div></div>
      <Toolbar search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} filters={filters} placeholder={`Buscar ${label}...`} extraFilterFields={extraFilterFields} extraFilters={extraFilters} onExtraFilterChange={(field, value) => setExtraFilters((currentFilters) => ({ ...currentFilters, [field]: value }))} />
      <div className="com-table-wrap"><table className={`com-table com-table-${page}`}><thead><tr>{titles[page].map((title) => <th key={title}>{title}</th>)}<th aria-label="Ações" /></tr></thead><tbody>{items.map((item, index) => <tr key={item.name || item.title}><td>{page === 'leads' ? <Identity name={item.name} sub={item.email} initials={item.initials} tone={item.tone} /> : page === 'clientes' || page === 'empresas' || page === 'contatos' ? <Identity name={item.name} sub={page === 'contatos' ? item.role : page === 'clientes' ? item.since : item.segment} initials={item.initials} tone={item.tone} /> : <div className="com-table-primary"><b>{item.title}</b><small>{item.code}</small></div>}</td>
        {page === 'leads' && <><td><b>{item.company}</b><small>{item.service}</small></td><td><Badge tone={item.source === 'Instagram' ? 'purple' : item.source === 'Indicação' ? 'green' : 'blue'}>{item.source}</Badge></td><td><Badge tone={stageTone(item.stage)}>{item.stage}</Badge></td><td className="com-amount">{item.value}</td><td className="com-muted">{item.date}</td></>}
        {page === 'clientes' && <><td><b>{item.person}</b><small>{item.email}</small></td><td><span className="com-text-line">{item.segment}</span><small>{item.email}</small></td><td>{item.projects}</td><td className="com-amount">{item.value}</td><td><Badge tone={item.status === 'Ativo' ? 'green' : 'amber'}>{item.status}</Badge></td></>}
        {page === 'empresas' && <><td>{item.segment}</td><td>{item.city}</td><td>{item.size}</td><td>{item.people}</td><td><Badge tone={item.status === 'Cliente' ? 'green' : 'blue'}>{item.status}</Badge></td></>}
        {page === 'contatos' && <><td><a className="com-email" href={`mailto:${item.email}`}><Mail size={13} />{item.email}</a></td><td><a className="com-phone" href={`tel:${item.phone.replace(/\D/g, '')}`}><Phone size={13} />{item.phone}</a></td><td className="com-muted">{item.last}</td><td><Badge tone={item.status === 'Decisor' || item.status === 'Decisora' ? 'purple' : 'blue'}>{item.status}</Badge></td></>}
        {(page === 'propostas' || page === 'contratos') && <><td><b>{item.client}</b><small>{item.code}</small></td><td className="com-amount">{item.value}</td>{page === 'propostas' ? <><td><Badge tone={item.tone}>{item.status}</Badge></td><td className="com-muted">{item.date}</td></> : <><td><div className="com-contract-progress"><div className="com-progress"><i style={{ width: `${item.progress}%` }} /></div><small>{item.renewal}</small></div></td><td><Badge tone={item.tone}>{item.status}</Badge></td></>}</>}
        <td><button className="com-row-more" aria-label={`Ações para ${item.name || item.title}`} onClick={() => { setSelectedItem(item); setStatusDraft(item.stage || item.status || 'Ativo'); setSendTo(item.email || ''); setRetryKey(['sending', 'failed'].includes(item.emailDelivery?.status) ? item.emailDelivery.key || '' : ''); setSignerName(item.signerName || item.person || ''); setSignerEmail(item.email || ''); setContractDocDraft(item.documentText || (page === 'contratos' ? contractText(item) : '')); }}><Ellipsis size={18} /></button></td></tr>)}</tbody></table>
        {items.length === 0 && <EmptyState query={search} noun={label} onClear={() => { setSearch(''); setFilter('Todos'); }} />}</div>
      <div className="com-table-footer"><span>Mostrando <b>{items.length ? 1 : 0}–{items.length}</b> de <b>{items.length}</b> {label}</span><div><button disabled>Anterior</button><button className="current">1</button><button disabled>Próxima</button></div></div>
    </section>
    {selectedItem && (page === 'clientes' ? <ClientProfileModal client={selectedItem} onClose={() => setSelectedItem(null)} onUpdate={(updated) => onUpdate?.(selectedItem, updated)} onAction={onAction} /> : <div className="com-modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) setSelectedItem(null); }}><section className="com-create-modal"><header><div><small>{page.toUpperCase()} · REGISTRO</small><h2>{selectedItem.name || selectedItem.title}</h2></div><button aria-label="Fechar" onClick={() => setSelectedItem(null)}>×</button></header><div className="com-record-details"><span>Cliente / empresa<b>{selectedItem.client || selectedItem.company || selectedItem.name || '—'}</b></span><span>Valor<b>{selectedItem.value || selectedItem.price || 'A definir'}</b></span><span>Contato<b>{selectedItem.email || selectedItem.person || selectedItem.role || '—'}</b></span><span>Detalhes<b>{selectedItem.service || selectedItem.segment || selectedItem.description || selectedItem.code || '—'}</b></span></div>{page === 'propostas' && <div className="com-proposal-detail"><b>Escopo</b><p>{selectedItem.scope || selectedItem.service || 'Escopo nao detalhado'}</p><span>Prazo: {selectedItem.deadline || 'A definir'} ? Pagamento: {selectedItem.paymentTerms || 'A combinar'}</span></div>}{page === 'propostas' && <div className="com-proposal-email"><label>Enviar para<input type="email" required value={sendTo} onChange={(event) => { setSendTo(event.target.value); setRetryKey(''); }} placeholder="cliente@empresa.com" /></label><label>Enviar com<select value={emailProvider} onChange={(event) => { setEmailProvider(event.target.value); setRetryKey(''); }}><option value="resend">Resend</option><option value="google">Gmail (Google Workspace)</option></select></label><small>{selectedItem.emailDelivery?.status === 'sent' ? `Ultimo envio confirmado em ${new Date(selectedItem.emailDelivery.sentAt).toLocaleString('pt-BR')}` : selectedItem.emailDelivery?.status === 'failed' ? 'O envio anterior nao foi confirmado. Repetir mantem a mesma chave idempotente.' : 'O e-mail inclui escopo, valor, prazo e condicoes da proposta.'}</small><button type="button" className="com-primary" disabled={sendingProposal || !sendTo.trim()} onClick={async () => { if (!window.confirm(`Enviar esta proposta para ${sendTo.trim()} usando ${emailProvider === 'google' ? 'Gmail' : 'Resend'}?`)) return; const key = retryKey || crypto.randomUUID(); setRetryKey(key); setSendingProposal(true); try { await onSendProposal?.(selectedItem, sendTo.trim(), key, emailProvider); setSelectedItem({ ...selectedItem, email: sendTo.trim(), status: 'Enviada', tone: 'blue', emailDelivery: { status: 'sent', recipient: sendTo.trim(), sentAt: new Date().toISOString() } }); setStatusDraft('Enviada'); setRetryKey(''); } catch (error) { onAction(error.message || 'Nao foi possivel enviar a proposta.'); } finally { setSendingProposal(false); } }}><Send size={14}/>{sendingProposal ? 'Enviando...' : selectedItem.emailDelivery?.status === 'sent' ? 'Enviar novamente' : 'Enviar proposta'}</button></div>}{page === 'contratos' && <div className="com-proposal-detail"><b>Termos do contrato</b><p>{selectedItem.scope || selectedItem.service || 'Escopo pendente de revisao'}</p><span>Prazo: {selectedItem.deadline || selectedItem.renewal || 'A definir'} ? Condicao: {selectedItem.paymentTerms || 'A combinar'}</span></div>}{page === 'contratos' && <div className="com-contract-document"><strong>Documento base para assinatura</strong><p>Revise e complete o texto antes do envio. Campos entre colchetes bloqueiam a assinatura. O contrato so sera enviado quando voce clicar no botao.</p><textarea rows={16} value={contractDocDraft} onChange={(event) => setContractDocDraft(event.target.value)} aria-label="Texto integral do contrato"/><button type="button" className="com-secondary" onClick={() => downloadContract({ ...selectedItem, documentText: contractDocDraft })}><Download size={14}/>Baixar modelo HTML para revisao</button>{selectedItem.clicksign?.envelopeId ? <div className="com-proposal-email"><b>Clicksign ? {selectedItem.clicksign.status || 'running'}</b><small>Signatario: {selectedItem.clicksign.signerEmail || signerEmail} ? notificacao: {selectedItem.clicksign.notificationStatus || 'pendente'}</small><div className="com-toolbar-actions"><button type="button" className="com-secondary" disabled={syncingContract} onClick={syncContract}><RefreshCw size={14}/>{syncingContract ? 'Sincronizando...' : 'Sincronizar status'}</button>{selectedItem.clicksign.notificationStatus !== 'sent' && <button type="button" className="com-secondary" onClick={notifyContractSigner}><Send size={14}/>Reenviar notificacao</button>}</div></div> : selectedItem.clicksign ? <div className="com-proposal-detail"><b>Envio interrompido</b><p>A solicitacao foi interrompida antes da confirmacao do ID do envelope. Consulte a conta Clicksign pelo codigo deste contrato antes de tentar novamente; o Nexo bloqueia um segundo envio automatico para evitar duplicidade.</p></div> : <div className="com-proposal-email"><label>Nome completo do signatario<input required value={signerName} onChange={(event) => setSignerName(event.target.value)} placeholder="Nome Sobrenome"/></label><label>E-mail do signatario<input required type="email" value={signerEmail} onChange={(event) => setSignerEmail(event.target.value)} placeholder="cliente@empresa.com"/></label><button type="button" className="com-primary" disabled={sendingContract || !signerName.trim() || !signerEmail.trim() || contractDocDraft.length < 100} onClick={sendContract}><Send size={14}/>{sendingContract ? 'Preparando envelope...' : 'Enviar para assinatura Clicksign'}</button></div>}</div>}{page !== 'servicos' && <StatusControl page={page} statusDraft={statusDraft} setStatusDraft={setStatusDraft} />}<footer><button type="button" className="com-secondary com-delete-action" onClick={() => { onDelete?.(selectedItem); setSelectedItem(null); }}>Excluir</button><span />{page === 'propostas' && selectedItem.status !== 'Aprovada' && <button type="button" className="com-secondary" onClick={() => { onAccept?.(selectedItem); setSelectedItem(null); }}>Aceitar e iniciar</button>}<button type="button" className="com-primary" onClick={() => { onUpdate?.(selectedItem, page === 'leads' ? { stage: statusDraft } : { status: statusDraft, tone: ['Ativo','Aprovada','Assinado','Cliente','Fechado'].includes(statusDraft) ? 'green' : 'amber' }); setSelectedItem(null); }}>Salvar alteração</button></footer></section></div>)}
  </>;
}

function Identity({ name, sub, initials, tone }) { return <div className="com-identity"><Avatar initials={initials} tone={tone} /><span><b>{name}</b><small>{sub}</small></span></div>; }
function EmptyState({ query, noun, onClear }) { return <div className="com-empty"><span><Search size={20} /></span><b>Nenhum {noun} encontrado</b><small>{query ? 'Tente outro termo ou ajuste os filtros.' : 'Nenhum item corresponde aos filtros selecionados.'}</small><button onClick={onClear}>Limpar busca e filtros</button></div>; }
function stageTone(stage = '') { const value = String(stage || ''); return value.includes('Novo') ? 'blue' : value.includes('Qualificação') ? 'purple' : value.includes('Reunião') ? 'amber' : 'green'; }

function PipelineView({ items = datasets.leads, onMove, onUpdate, onAction, onSearch, search, mode }) {
  const [selectedDeal, setSelectedDeal] = useState(null);
  const [dealDraft, setDealDraft] = useState({});
  const openDeal = (item) => { setSelectedDeal(item); setDealDraft({ stage: item.stage || 'Novo lead', value: item.value || '', chance: item.chance ?? 50, source: item.source || 'Manual', service: item.service || '', owner: item.owner || 'GS', closeDate: item.closeDate || '', nextAction: item.nextAction || '', notes: item.notes || '' }); };
  const saveDeal = (event) => { event.preventDefault(); const { stage, ...fields } = dealDraft; onUpdate?.(selectedDeal, { ...fields, stage }); setSelectedDeal(null); };
  const stagesFull = ['Novo lead', 'Contato realizado', 'Reunião agendada', 'Diagnóstico', 'Proposta enviada', 'Negociação', 'Fechado', 'Perdido'];
  const stageColors = ['blue', 'purple', 'amber', 'blue', 'green', 'amber', 'green', 'red'];
  return <>
    <div className="com-metrics"><Metric label="Oportunidades abertas" value={String(items.filter((item) => !['Fechado', 'Perdido'].includes(item.stage)).length)} detail="em acompanhamento" icon={Users} tone="blue" /><Metric label="Valor total" value={`R$ ${items.reduce((sum, item) => sum + (Number(String(item.value).replace(/[^\d,]/g, '').replace(',', '.')) || 0), 0).toLocaleString('pt-BR')}`} detail="valor potencial" icon={CircleDollarSign} tone="green" /><Metric label="Ticket médio" value={`R$ ${Math.round(items.reduce((sum, item) => sum + (Number(String(item.value).replace(/[^\d,]/g, '').replace(',', '.')) || 0), 0) / Math.max(items.length, 1)).toLocaleString('pt-BR')}`} detail="por oportunidade" icon={Wallet} tone="purple" /><Metric label="Conversão" value={`${Math.round(items.filter((item) => item.stage === 'Fechado').length / Math.max(items.length, 1) * 100)}%`} detail="negócios ganhos" icon={ArrowUpRight} tone="amber" /></div>
    <section className="com-pipeline-panel"><div className="com-panel-heading"><div><h2>{mode === 'crm' ? 'Resumo do pipeline' : 'Oportunidades por etapa'}</h2><p>Visão do avanço comercial <span>·</span> <span className="com-live"><i /> sincronizado no workspace</span></p></div><div className="com-pipeline-actions"><label className="com-search"><Search size={16} /><input value={search} onChange={(event) => onSearch(event.target.value)} placeholder="Buscar oportunidade..." aria-label="Buscar oportunidade" /></label><button className="com-secondary" onClick={() => onAction('O pipeline mostra todas as oportunidades cadastradas.') }><CalendarDays size={15} /> Todos os períodos <ChevronDown size={13} /></button><button className="com-primary compact" onClick={() => onAction('Use o botão Adicionar lead para cadastrar uma oportunidade.')}><Plus size={16} /> Oportunidade</button></div></div>
      <div className="com-stage-grid com-stage-grid-full">{stagesFull.map((stageName, index) => { const stageItems = items.filter((item) => (item.stage || 'Novo lead') === stageName && (!search.trim() || `${item.name} ${item.company} ${item.service}`.toLocaleLowerCase('pt-BR').includes(search.trim().toLocaleLowerCase('pt-BR')))); const sum = stageItems.reduce((amount, item) => amount + (Number(String(item.value).replace(/[^\d,]/g, '').replace(',', '.')) || 0), 0); return <section className="com-stage" key={stageName}><div className="com-stage-heading"><span className={`com-stage-dot ${stageColors[index]}`} /><b>{stageName}</b><span className="com-stage-count">{stageItems.length}</span><button aria-label={`Mais opções: ${stageName}`} onClick={() => onAction(`Etapa: ${stageName}`)}><MoreHorizontal size={17} /></button></div><small className="com-stage-total">{sum ? `R$ ${sum.toLocaleString('pt-BR')}` : 'Sem valor previsto'}</small>
        {stageItems.map((item) => <article className="com-deal-card" key={item.name}><div className="com-deal-top"><Avatar initials={item.initials} tone={item.tone} small /><button aria-label={`Ações para ${item.name}`} onClick={() => onAction(`Oportunidade ${item.name} · ${item.email || 'sem e-mail'}`)}><MoreHorizontal size={16} /></button></div><b>{item.name}</b><small>{item.company}</small><div className="com-deal-service">{item.service}</div><div className="com-deal-bottom"><strong>{item.value}</strong><span>{item.date}</span></div><div className="com-deal-actions"><button className="com-deal-open" onClick={() => openDeal(item)}>Ver oportunidade <ArrowRight size={14} /></button>{index < 6 && <button className="com-deal-open" onClick={() => onMove?.(item, stagesFull[index + 1])}>Avançar etapa <ArrowRight size={14} /></button>}</div></article>)}{!stageItems.length && <p className="com-stage-empty">Nenhuma oportunidade</p>}<button className="com-add-stage" onClick={() => onAction(`Cadastre um lead e mova-o para ${stageName}.`)}><Plus size={15} /> Adicionar oportunidade</button></section>; })}</div>
    </section><section className="com-insight"><span><Sparkles size={17} /></span><p><b>Pipeline da agência</b> As etapas, oportunidades e valores são atualizados conforme os registros salvos.</p><button onClick={() => onAction('Confira as oportunidades em cada etapa do pipeline.')}>Ver resumo <ArrowRight size={14} /></button></section>
    {selectedDeal && <div className="com-modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setSelectedDeal(null); }}><form className="com-create-modal com-deal-modal" onSubmit={saveDeal}><header><div><small>OPORTUNIDADE ? {selectedDeal.company}</small><h2>{selectedDeal.name}</h2></div><button type="button" aria-label="Fechar" onClick={() => setSelectedDeal(null)}>?</button></header><div className="com-deal-edit-fields"><label>Etapa<select value={dealDraft.stage} onChange={(event) => setDealDraft({ ...dealDraft, stage: event.target.value })}>{stagesFull.map((stage) => <option key={stage}>{stage}</option>)}</select></label><label>Valor estimado<input value={dealDraft.value} onChange={(event) => setDealDraft({ ...dealDraft, value: event.target.value })}/></label><label>Chance de fechamento (%)<input type="number" min="0" max="100" value={dealDraft.chance} onChange={(event) => setDealDraft({ ...dealDraft, chance: Number(event.target.value) })}/></label><label>Origem<input value={dealDraft.source} onChange={(event) => setDealDraft({ ...dealDraft, source: event.target.value })}/></label><label>Servico interessado<input value={dealDraft.service} onChange={(event) => setDealDraft({ ...dealDraft, service: event.target.value })}/></label><label>Responsavel<input value={dealDraft.owner} onChange={(event) => setDealDraft({ ...dealDraft, owner: event.target.value })}/></label><label>Fechamento previsto<input type="date" value={dealDraft.closeDate} onChange={(event) => setDealDraft({ ...dealDraft, closeDate: event.target.value })}/></label><label>Proxima acao<input value={dealDraft.nextAction} onChange={(event) => setDealDraft({ ...dealDraft, nextAction: event.target.value })}/></label><label className="wide">Observacoes<textarea rows="3" value={dealDraft.notes} onChange={(event) => setDealDraft({ ...dealDraft, notes: event.target.value })}/></label></div><p className="com-deal-contact">Contato: {selectedDeal.email || 'email nao informado'} ? {selectedDeal.phone || 'telefone nao informado'}</p><footer><button type="button" className="com-secondary" onClick={() => setSelectedDeal(null)}>Cancelar</button><button type="submit" className="com-primary"><Check size={14}/>Salvar oportunidade</button></footer></form></div>}
  </>;
}
function ServicesView({ items, totalItems, clients, onAction, onUpdate, onDelete, onImportCatalog, onCreateProject, search, setSearch, catalogImporting = false, catalogSeedState = 'idle' }) {
  const blank = { name: '', category: 'Presença digital', description: '', price: '', cadence: 'Projeto fechado', duration: '', cost: '', responsible: '', checklist: '', proposalTemplate: '', contractTemplate: '' };
  const [selected, setSelected] = useState(null);
  const [draft, setDraft] = useState(blank);
  const [clientId, setClientId] = useState('');
  const [tab, setTab] = useState('Detalhes');
  const parsePrice = (value) => Number(String(value || '').replace(/[^\d,]/g, '').replace(',', '.')) || 0;
  const recurring = items.filter((item) => /mensal|recorr/i.test(item.cadence || '')).length;
  const avgPrice = items.length ? Math.round(items.reduce((sum, item) => sum + parsePrice(item.price), 0) / items.length) : 0;
  const save = (event) => {
    event.preventDefault();
    const next = { ...selected, ...draft, name: draft.name.trim(), price: draft.price ? `A partir de R$ ${draft.price}` : 'A combinar', cadence: draft.cadence || 'Projeto fechado', duration: draft.duration || 'A definir', cost: draft.cost || 'A definir', responsible: draft.responsible || 'Equipe', templateTasks: draft.checklist.split('\n').map((line) => line.trim()).filter(Boolean), proposalTemplate: draft.proposalTemplate, contractTemplate: draft.contractTemplate, margin: parsePrice(draft.price) ? Math.round((parsePrice(draft.price) - parsePrice(draft.cost)) / parsePrice(draft.price) * 100) : 0, color: selected?.color || 'blue' };
    onUpdate(selected, next); setSelected(next); setTab('Detalhes');
  };
  const startProject = async () => {
    const clientRecord = clients.find((item) => String(item.id) === clientId);
    if (!clientRecord) return onAction('Selecione um cliente cadastrado para criar o projeto.');
    if (!onCreateProject) return onAction('A gravação de projetos não está disponível no momento.');
    const records = buildServiceProject(selected, clientRecord);
    try {
      await onCreateProject(records.project, records.tasks);
      onAction(`Projeto e ${records.tasks.length} tarefas salvos para ${clientRecord.name}.`);
      setClientId(''); setTab('Detalhes');
    } catch (error) { onAction(error.message || 'Não foi possível salvar o projeto e as tarefas.'); }
  };
  const editService = (item) => { setSelected(item); setDraft({ name: item.name || '', category: item.category || 'Geral', description: item.description || '', price: String(item.price || '').replace(/^A partir de R\$\s*/, ''), cadence: item.cadence || 'Projeto fechado', duration: item.duration || '', cost: item.cost || '', responsible: item.responsible || '', checklist: (item.templateTasks || []).join('\n'), proposalTemplate: item.proposalTemplate || '', contractTemplate: item.contractTemplate || '' }); setTab('Detalhes'); };
  return <><div className="com-metrics"><Metric label="Serviços cadastrados" value={String(totalItems ?? items.length)} detail="no catálogo atual" icon={Sparkles} tone="blue" /><Metric label="Mais contratado" value={items[0]?.name || '—'} detail="destaque do catálogo" icon={ArrowUpRight} tone="green" /><Metric label="Serviços recorrentes" value={String(recurring)} detail="com cobrança recorrente" icon={RefreshCw} tone="purple" /><Metric label="Preço médio base" value={avgPrice ? `R$ ${avgPrice.toLocaleString('pt-BR')}` : '—'} detail="valor médio cadastrado" icon={Wallet} tone="amber" /></div><div className="com-service-toolbar"><div><h2>Catálogo de serviços</h2><p>{catalogSeedState === 'loading' ? 'Incluindo os serviços que você informou; preços e prazos permanecem sem valores inventados.' : catalogSeedState === 'error' ? 'Não foi possível importar o catálogo automaticamente. Use o botão para tentar novamente.' : 'Preços e prazos ficam em aberto para você configurar antes de gerar propostas.'}</p></div><label className="com-search"><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar serviço..." aria-label="Buscar serviço" /></label><button className="com-secondary" type="button" onClick={onImportCatalog} disabled={catalogImporting}><Download size={14}/>{catalogImporting ? "Preparando catálogo…" : totalItems > 0 ? "Completar modelos do catálogo" : "Cadastrar catálogo informado"}</button></div><div className="com-service-grid">{items.map((item) => <article className="com-service-card" key={item.id || item.name}><div className="com-service-top"><span className={`com-service-icon ${item.color}`}><Sparkles size={19} /></span><button aria-label={`Mais opções para ${item.name}`} onClick={() => editService(item)}><MoreHorizontal size={18} /></button></div><Badge tone={item.color}>{item.catalogGroup || item.category}</Badge><h3>{item.name}</h3><p>{item.description || 'Descrição e escopo a configurar.'}</p><div className="com-service-price"><b>{item.price || 'Preço a definir'}</b><span>{item.cadence}</span></div><button className="com-service-link" onClick={() => editService(item)}>Configurar serviço <ArrowRight size={15} /></button></article>)}{items.length === 0 && <EmptyState query={search} noun="serviços" onClear={() => setSearch('')} />}</div>
    {selected && <div className="com-modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setSelected(null); }}><section className="com-create-modal com-service-editor"><header><div><small>CATÁLOGO · TEMPLATE DE ENTREGA</small><h2>{selected.name}</h2></div><button type="button" aria-label="Fechar" onClick={() => setSelected(null)}>×</button></header><nav className="com-service-editor-tabs">{['Detalhes', 'Template do projeto'].map((name) => <button type="button" className={tab === name ? 'active' : ''} onClick={() => setTab(name)} key={name}>{name}</button>)}</nav>{tab === 'Detalhes' ? <form onSubmit={save}><div className="com-service-editor-fields"><label>Nome<input required value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} /></label><label>Categoria<select value={draft.category} onChange={(e) => setDraft({ ...draft, category: e.target.value })}>{['Presença digital','Conversão','Desenvolvimento','Automação','Conteúdo','Marca','Performance','Suporte','Consultoria','Geral'].map((value) => <option key={value}>{value}</option>)}</select></label><label>Preço base (R$)<input inputMode="decimal" value={draft.price} onChange={(e) => setDraft({ ...draft, price: e.target.value })} placeholder="4500,00" /></label><label>Modelo de cobrança<select value={draft.cadence} onChange={(e) => setDraft({ ...draft, cadence: e.target.value })}><option>Projeto fechado</option><option>Pagamento por etapas</option><option>Mensal</option><option>Anual</option><option>Recorrência personalizada</option></select></label><label>Prazo médio<input value={draft.duration} onChange={(e) => setDraft({ ...draft, duration: e.target.value })} placeholder="Ex.: 20 dias úteis" /></label><label>Custo estimado<input value={draft.cost} onChange={(e) => setDraft({ ...draft, cost: e.target.value })} placeholder="Ex.: R$ 1.200" /></label><label>Responsável padrão<input value={draft.responsible} onChange={(e) => setDraft({ ...draft, responsible: e.target.value })} placeholder="Iniciais ou nome" /></label><label className="wide">Descrição<textarea rows="3" value={draft.description} onChange={(e) => setDraft({ ...draft, description: e.target.value })} /></label><label>Margem estimada<input readOnly value={parsePrice(draft.price) ? `${Math.round((parsePrice(draft.price) - parsePrice(draft.cost)) / parsePrice(draft.price) * 100)}%` : "Informe preco e custo"} /></label><label className="wide">Modelo de proposta<textarea rows="3" value={draft.proposalTemplate} onChange={(e) => setDraft({ ...draft, proposalTemplate: e.target.value })} placeholder="Escopo e condicoes comerciais padrao" /></label><label className="wide">Modelo de contrato<textarea rows="3" value={draft.contractTemplate} onChange={(e) => setDraft({ ...draft, contractTemplate: e.target.value })} placeholder="Termos padrao para revisao" /></label></div><footer><button type="button" className="com-secondary com-delete-action" onClick={() => { onDelete(selected); setSelected(null); }}>Excluir serviço</button><span/><button className="com-primary" type="submit"><Check size={14}/>Salvar alterações</button></footer></form> : <div className="com-service-template"><label>Checklist padrão<textarea rows="8" value={draft.checklist} onChange={(e) => setDraft({ ...draft, checklist: e.target.value })} placeholder={'Briefing\nReceber materiais\nCriar primeira versão\nRevisão do cliente\nPublicação'} /></label><p>Uma tarefa será criada para cada linha quando você iniciar um projeto por este serviço.</p><div className="com-project-from-template"><label>Cliente do projeto<select required value={clientId} onChange={(e) => setClientId(e.target.value)}><option value="">Selecione um cliente cadastrado</option>{clients.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><button className="com-primary" type="button" disabled={!clientId} onClick={startProject}><Plus size={14}/>Criar projeto e tarefas</button></div><button className="com-secondary" type="button" onClick={save}>Salvar template</button></div>}</section></div>}
  </>;
}
